    if(key==='gapBasis'&&value!==p.gapBasis&&(p.preGaps.some(v=>v!==null)||p.postGaps.some(v=>v!==null))){p.preGaps=Array(p.count).fill(null);p.postGaps=Array(p.count).fill(null);p.edgeCondition='unknown';p.disposition='';renderFitup(true);notify('量測方向或位置改變，請重新量測。');}
