$('duplicate-joint').addEventListener('click',()=>safeAction(()=>{const nextPlan=clearFitRecords(state.fabrication,state.params);state.metadata={...state.metadata,id:nextJointID(state.metadata.id),revision:'1'};$('joint-id').value=state.metadata.id;state.fabrication=nextPlan;renderFitup(true);compute();notify(`已建立 ${state.metadata.id}，沿用尺寸與工藝設定；實測紀錄已清空。`);},false));
$('undo-change').addEventListener('click',()=>safeAction(()=>{clearTimeout(timer);const pending=lastValid&&(JSON.stringify(lastValid.params)!==JSON.stringify(state.params)||JSON.stringify(lastValid.fabrication)!==JSON.stringify(state.fabrication));const previous=(!state.result.valid||!!state.fabricationError||pending)&&lastValid?lastValid:history.pop();if(previous){loadParameters(previous.params,previous.metadata,false,previous.inputSetup,previous.fabrication??emptyFabricationPlan());notify('已復原上一組有效尺寸與加工紀錄。');}},false));
$('save-favorite').addEventListener('click',()=>safeAction(()=>{compute();if(!state.result.valid)throw new Error('請先修正尺寸。');const item={name:`${state.metadata.id} · Ø${fmt(state.params.mainOD)}/Ø${fmt(state.params.branchOD)} · ${fmt(state.params.angle)}°`,params:{...state.params},inputSetup:{...inputSetup},fabrication:clearFitRecords(state.fabrication,state.params)};const candidate=favorites.slice(),index=candidate.findIndex(f=>f.name===item.name);if(index>=0)candidate[index]=item;else candidate.unshift(item);const limited=candidate.slice(0,12);try{localStorage.setItem('pipe-fabrication:favorites',JSON.stringify(limited));}catch{throw new Error('瀏覽器無法記住尺寸，請使用儲存專案下載。');}favorites=limited;renderFavorites();notify('已記住這組尺寸，僅儲存在此瀏覽器。');},false));
$('favorite-select').addEventListener('change',()=>{$('apply-favorite').disabled=$('favorite-select').value==='';});$('apply-favorite').addEventListener('click',()=>safeAction(()=>{const f=favorites[Number($('favorite-select').value)];if(!f)throw new Error('請先選擇常用尺寸。');loadParameters(f.params,state.metadata,true,f.inputSetup,f.fabrication??emptyFabricationPlan());notify('已套用常用尺寸並重新驗證。');},false));
$('download-report').addEventListener('click',()=>safeAction(()=>{downloadText(buildReportHTML(tableResult(),state.metadata,reportOptions()),filename('現場報告.html'),'text/html;charset=utf-8');notify('報告已下載，可離線開啟並列印成 PDF。');}));
$('print-report').addEventListener('click',()=>safeAction(()=>{previewReport(reportOptions());}));
$('report-frame').addEventListener('load',fitReportPreview);new ResizeObserver(fitReportPreview).observe($('report-frame'));
$('close-preview').addEventListener('click',()=>$('report-preview').close());$('preview-download').addEventListener('click',()=>downloadText(previewHTML,filename(previewSuffix),'text/html;charset=utf-8'));$('preview-print').addEventListener('click',()=>{try{$('report-frame').contentWindow.focus();$('report-frame').contentWindow.print();}catch{downloadText(previewHTML,filename(previewSuffix),'text/html;charset=utf-8');notify('請開啟下載的列印檔，選擇 100% 列印。');}});
$('pattern-detail').addEventListener('click',()=>{patternDetail=!patternDetail;renderPattern();});
new ResizeObserver(()=>renderPattern()).observe($('pattern-scroll'));
try{const saved=localStorage.getItem('pipe-fabrication:last');if(saved){const project=readProjectJSON(saved),params={...DEFAULT_PARAMS,...project.params};if(computeJoint(params).valid){state.params=params;state.fabrication=reconcileFitRecords(project.fabrication??emptyFabricationPlan(),params).plan;syncInputSetup();state.metadata={...state.metadata,...project.metadata};$('joint-id').value=state.metadata.id;try{const savedSetup=JSON.parse(localStorage.getItem('pipe-fabrication:input-setup')||'null');if(savedSetup?.paramsKey===JSON.stringify(params))syncInputSetup(savedSetup.setup);}catch{}}}}catch{}
try{const saved=JSON.parse(localStorage.getItem('pipe-fabrication:favorites')||'[]');if(Array.isArray(saved))favorites=saved.filter(f=>typeof f.name==='string'&&f.name.length<140&&f.params&&(()=>{try{validateProjectParams(f.params);return computeJoint({...DEFAULT_PARAMS,...f.params}).valid;}catch{return false;}})()).slice(0,12);}catch{}
renderFavorites();renderForm();renderFitup(true);compute();showWorkspace('paper');

// Optional browser-native tools act on the same validated state as the form.
function registerTools() {
  if(!document.modelContext?.registerTool)return;
  const context=document.modelContext,lifecycle=new AbortController(),textResult=value=>({content:[{type:'text',text:JSON.stringify(value)}]});
  const register=tool=>Promise.resolve(context.registerTool(tool,{signal:lifecycle.signal})).catch(error=>console.warn(error.message));
  register({name:'read_pipe_joint',description:'Read the visible pipe joint dimensions, selected template and geometric fabrication validation.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute:async()=>textResult({params:state.params,metadata:state.metadata,selectedTemplate:state.template,fabrication:state.fabrication,fabricationError:state.fabricationError,fitup:{pre:fitPhaseStatus(state.fabrication),post:fitPhaseStatus(state.fabrication,'post')},inputSetup:{...inputSetup},valid:state.result.valid,fabricationReady:fabricationReadiness(state.result).ready&&!state.fabricationError,precision:state.result.precision,verification:state.result.verification,errors:state.result.errors,templates:state.result.templates.map(t=>({id:t.id,title:t.title,width:t.width,height:t.height}))})});
  register({name:'configure_pipe_joint',description:'Apply dimensions to the visible single main/branch pipe joint. Invalid geometry is rejected without changing current state.',inputSchema:{type:'object',properties:{params:{type:'object',properties:Object.fromEntries(Object.entries(DEFAULT_PARAMS).map(([k,v])=>[k,{type:typeof v==='boolean'?'boolean':typeof v==='number'?'number':'string'}])),additionalProperties:false}},required:['params'],additionalProperties:false},annotations:{readOnlyHint:false},execute:async({params})=>{if(!params||typeof params!=='object'||Array.isArray(params))throw new Error('尺寸參數必須是物件。');const candidate={...state.params,...params};validateProjectParams(candidate);const result=computeJoint(candidate);if(!result.valid)throw new Error(result.errors.map(e=>e.message).join(' '));state.params=candidate;syncInputSetup();renderForm();compute();return textResult({valid:state.result.valid,fabricationReady:fabricationReadiness(state.result).ready&&!state.fabricationError,precision:state.result.precision,verification:state.result.verification});}});
  register({name:'select_pipe_template',description:'Select and inspect a current manufacturing template in the drawing pane; does not create or send files.',inputSchema:{type:'object',properties:{id:{type:'string'}},required:['id'],additionalProperties:false},annotations:{readOnlyHint:false},execute:async({id})=>{if(!state.result.templates.some(t=>t.id===id))throw new Error('未知的零件圖面。');state.template=id;compute();const t=currentTemplate();return textResult({id:t.id,title:t.title,width:t.width,height:t.height,basis:t.basis});}});
  window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true});
}
try{registerTools();}catch(error){console.warn('Browser model context unavailable:',error.message);}
